<?php $title='Edit User';require __DIR__.'/includes/header.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$u=$s->fetch();if(!$u)exit('User not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=$_POST['status']==='active'?'active':'inactive';$s=db()->prepare('UPDATE users SET full_name=?,role=?,status=?'.(trim($_POST['password']??'')!==''?',password_hash=?':'').' WHERE id=?');$args=[trim($_POST['full_name']),$_POST['role'],$status];if(trim($_POST['password']??'')!=='')$args[]=password_hash($_POST['password'],PASSWORD_DEFAULT);$args[]=$id;$s->execute($args);flash('success','User updated.');redirect('users_list.php');}?><h1>Edit user</h1><div class="card"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="grid grid-2"><div class="field"><label>Full name</label><input name="full_name" value="<?=e($u['full_name'])?>" required></div><div class="field"><label>Username</label><input value="<?=e($u['username'])?>" disabled></div><div class="field"><label>New password (optional)</label><input type="password" name="password" minlength="8"></div><div class="field"><label>Role</label><select name="role"><option value="staff" <?=$u['role']==='staff'?'selected':''?>>Staff</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Admin</option></select></div><div class="field"><label>Status</label><select name="status"><option value="active" <?=$u['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$u['status']==='inactive'?'selected':''?>>Inactive</option></select></div></div><button class="btn">Save changes</button></form></div><?php require __DIR__.'/includes/footer.php';
